      root.innerHTML=`<div class="v33-pwa-sim"><h3>${esc(exercise.prompt)}</h3><div class="v33-network"><button data-net="online" class="active">Online</button><button data-net="offline">Offline</button></div><div data-pwa-status class="v33-pwa-status"></div><ul>${exercise.assets.map(a=>`<li><label><input type="checkbox" data-asset value="${esc(a)}"> Cachear ${esc(a)}</label></li>`).join('')}</ul><button data-test class="btn primary">Testar estratégia</button></div>`;let mode='online';const paint=()=>{const checked=[...root.querySelectorAll('[data-asset]:checked')].map(x=>x.value);root.querySelector('[data-pwa-status]').textContent=mode==='online'?'Rede disponível: recursos podem ser buscados.':checked.length?`Offline: ${checked.join(', ')} permanecem disponíveis.`:'Offline: nenhum recurso essencial foi cacheado.';};root.querySelectorAll('[data-net]').forEach(b=>b.onclick=()=>{mode=b.dataset.net;root.querySelectorAll('[data-net]').forEach(x=>x.classList.toggle('active',x===b));paint();});root.addEventListener('change',paint);paint();root.querySelector('[data-test]').onclick=()=>{const checked=[...root.querySelectorAll('[data-asset]:checked')].map(x=>x.value);if(checked.length<2)return ctx.feedback('Selecione pelo menos dois recursos essenciais para o cache.','warn');ctx.progress.labData[key]={mode,assets:checked};ctx.save();ctx.markComplete('estratégia offline testada');};return;
