      let selected=Number(saved.selected??-1);const paint=()=>{const l=exercise.languages[selected];root.querySelectorAll('[data-lang]').forEach(b=>b.classList.toggle('active',Number(b.dataset.lang)===selected));root.querySelector('[data-lang-card]').innerHTML=l?`<h4>${esc(l.name)}</h4><dl><div><dt>Extensão</dt><dd>${esc(l.ext)}</dd></div><div><dt>Como executar</dt><dd><code>${esc(l.run)}</code></dd></div><div><dt>Usos</dt><dd>${esc(l.use)}</dd></div></dl>`:'<p>Escolha uma linguagem para comparar.</p>';};root.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.lang);paint();});paint();root.querySelector('[data-save]').onclick=()=>{if(selected<0)return ctx.feedback('Escolha ao menos uma linguagem.','warn');ctx.progress.labData[key]={selected,language:exercise.languages[selected].name};ctx.save();ctx.markComplete('linguagem comparada');};return;
